// Package jiratest is a fake Jira Cloud HTTP server over an in-memory dataset (jira-sync.md §6, ADR 0010).
//
// FROZEN CONTRACT: the types and signatures in this file. File ownership:
//
//	WP-07 server*.go faults*.go fixture*.go  (HTTP handlers except search, fault injection, fixture load/materialise)
//	WP-08 jql*.go (JQL subset parser/evaluator AND the POST /rest/api/3/search/jql + approximate-count handlers),
//	      cmd/fixturegen, testdata/fixture.json
package jiratest

import (
	_ "embed"
	"net/http"
	"sync"
	"time"
)

// DefaultFixture is testdata/fixture.json (generated by `go run ./cmd/fixturegen`).
//
//go:embed testdata/fixture.json
var DefaultFixture []byte

// Token is the only API token the fake accepts (any email).
const Token = "fake-token"

// Custom field ids the fake reports from GET /rest/api/3/field.
const (
	SprintFieldID  = "customfield_10020"
	RankFieldID    = "customfield_10019"
	FlaggedFieldID = "customfield_10021"
)

// ── Fixture file shape (all days relative to "today": 0 = today, -1 = yesterday) ──

type Fixture struct {
	Projects []FxProject `json:"projects"`
	Boards   []FxBoard   `json:"boards"`
	Users    []FxUser    `json:"users"`
	Issues   []FxIssue   `json:"issues"`
	Backlog  []FxBacklog `json:"backlog"`
}

type FxProject struct {
	ID   string `json:"id"`
	Key  string `json:"key"`
	Name string `json:"name"`
}

type FxBoard struct {
	ID         int        `json:"id"`
	Name       string     `json:"name"`
	Type       string     `json:"type"` // scrum|kanban|simple
	ProjectKey string     `json:"projectKey"`
	FilterID   int        `json:"filterId"`
	SubQuery   string     `json:"subQuery,omitempty"`
	Columns    []FxColumn `json:"columns"`
	Sprint     *FxSprint  `json:"sprint,omitempty"`
}

type FxColumn struct {
	Name     string   `json:"name"`
	Statuses []string `json:"statuses"` // status names
}

type FxSprint struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	StartDay int    `json:"startDay"`
	EndDay   int    `json:"endDay"`
}

type FxUser struct {
	AccountID   string `json:"accountId"`
	DisplayName string `json:"displayName"`
	AccountType string `json:"accountType,omitempty"` // default "atlassian"
}

type FxIssue struct {
	Key         string      `json:"key"`
	Type        string      `json:"type"` // Story|Bug|Task|Spike|Sub-task|Epic
	Summary     string      `json:"summary"`
	Assignee    string      `json:"assignee,omitempty"`
	Board       int         `json:"board"`
	InSprint    bool        `json:"inSprint"`
	FlaggedDays [][2]int    `json:"flaggedDays"` // [[fromDay, toDay]] inclusive; toDay 0 = still flagged today
	History     []FxHistory `json:"history"`     // oldest first; the last entry is the current status
	Commits     []int       `json:"commits"`     // one entry per commit, value = day
	PRs         []FxPR      `json:"prs"`
	Comments    []int       `json:"comments"` // one entry per comment, value = day
}

type FxHistory struct {
	Status string `json:"status"` // status name
	Days   int    `json:"days"`   // how many days the issue stayed in it (last entry: up to and including today)
}

type FxPR struct {
	ID     int    `json:"id"`
	Day    int    `json:"day"`
	Status string `json:"status"` // OPEN|MERGED|DECLINED
}

type FxBacklog struct {
	Key     string `json:"key"`
	Type    string `json:"type"`
	Summary string `json:"summary"`
	Board   int    `json:"board"`
}

// ── Materialised dataset (absolute times; what handlers serve) ──

type Dataset struct {
	Now      time.Time
	Projects []FxProject
	Boards   []DSBoard
	Users    []FxUser
	Statuses []DSStatus
	Types    []DSType
	Issues   []*DSIssue // board issues, then backlog issues; rank order = slice order within a board
}

type DSBoard struct {
	FxBoard
	Sprints []DSSprint // the fixture sprint as state "active", if any
}

type DSSprint struct {
	ID         int
	BoardID    int
	Name       string
	State      string // future|active|closed
	Start, End time.Time
}

type DSStatus struct {
	ID       string
	Name     string
	Category string // new|indeterminate|done
}

type DSType struct {
	ID        string
	Name      string
	Subtask   bool
	Hierarchy int // 1 = epic
}

type DSIssue struct {
	ID         string // numeric string, e.g. "10390"
	Key        string
	ProjectKey string
	BoardID    int
	TypeID     string
	StatusID   string
	Summary    string
	Assignee   string // account id, "" = unassigned
	SprintIDs  []int
	Rank       string // LexoRank-like, string order = rank
	Flagged    bool
	Created    time.Time
	Updated    time.Time
	Resolved   time.Time // zero = unresolved
	Changelog  []DSChange
	Comments   []DSComment
	Commits    []DSCommit
	PRs        []DSPR
}

type DSChange struct {
	ID      string
	At      time.Time
	FieldID string // "status", "assignee", FlaggedFieldID
	Field   string // "status", "assignee", "Flagged"
	From    string // status id / account id / "" ; flag: "" or "Impediment"
	To      string
}

type DSComment struct {
	ID     string
	At     time.Time
	Author string // account id
}

type DSCommit struct {
	SHA   string
	Repo  string
	At    time.Time
	Merge bool
}

type DSPR struct {
	ID         int
	Repo       string
	Status     string // OPEN|MERGED|DECLINED
	LastUpdate time.Time
}

// ── Server ──

type Throttle struct {
	Every      int           // every Nth request answers 429
	RetryAfter time.Duration // Retry-After header value (seconds, rounded up)
}

type FailStatus struct {
	PathPrefix string
	Code       int
	Count      int // first Count matching requests fail; 0 = all
}

type Options struct {
	Now       time.Time      // zero = time.Now(); fixture days are relative to Now's local date
	Loc       *time.Location // nil = time.Local
	Latency   time.Duration
	Throttle  *Throttle
	Fail      []FailStatus
	DevStatus string // "ok" (default) | "404" | "403" | "garbage"
	PageSize  int    // 0 = honour maxResults; >0 caps every page (forces paging)
	Addr      string // listen address; "" = 127.0.0.1:0 (random port). If it is taken, a random port is used.
}

// Request is one logged request (for "no network without a trigger" and request-budget tests).
type Request struct {
	Method string
	Path   string
	Query  string
	At     time.Time
	Status int
}

// Server is a running fake. Safe for concurrent use.
type Server struct {
	URL string // http://127.0.0.1:<port>

	mu           sync.Mutex
	ds           *Dataset
	opts         Options
	log          []Request
	unauthorized bool
	srv          *http.Server
	counter      int            // request counter for Throttle
	failed       map[string]int // FailStatus counters by PathPrefix
}
